import{_ as t}from"./chunks/ai-pipeline-01-overview.CyzW4Bfo.js";import{_ as i,o as r,c as a,a0 as n}from"./chunks/framework.DScjKhBS.js";const m=JSON.parse('{"title":"Operating model for constrained review capacity","description":"A practical review process when reviewer attention is limited but risk tolerance is unchanged.","frontmatter":{"title":"Operating model for constrained review capacity","description":"A practical review process when reviewer attention is limited but risk tolerance is unchanged."},"headers":[],"relativePath":"reports/pr-review-continuity/03-operating-model-for-constrained-review-capacity.md","filePath":"reports/pr-review-continuity/03-operating-model-for-constrained-review-capacity.md"}'),o={name:"reports/pr-review-continuity/03-operating-model-for-constrained-review-capacity.md"};function s(c,e,l,d,p,g){return r(),a("div",null,[...e[0]||(e[0]=[n('<figure class="report-section-image-wrapper" aria-labelledby="fig-pr-operating-model-caption"><img src="'+t+'" alt="A structured pipeline with checks converging to a human gate" loading="lazy" class="report-section-image"><figcaption id="fig-pr-operating-model-caption">Operating model: risk-tiered flow with deterministic checks before human approval</figcaption></figure><h1 id="operating-model-for-constrained-review-capacity" tabindex="-1">Operating model for constrained review capacity <a class="header-anchor" href="#operating-model-for-constrained-review-capacity" aria-label="Permalink to &quot;Operating model for constrained review capacity&quot;">​</a></h1><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>Risk-scaled review depth</strong>: not every PR needs the same depth, but high-risk PRs always get deep review.</li><li><strong>Deterministic checks first</strong>: automate what can be automated; reserve human cognition for design and risk judgment.</li><li><strong>Explicit accountability</strong>: every merge has a named accountable reviewer/owner.</li><li><strong>No autonomous merge path</strong>: AI commentary informs review, never replaces it.</li></ol><hr><h2 id="triage-matrix" tabindex="-1">Triage matrix <a class="header-anchor" href="#triage-matrix" aria-label="Permalink to &quot;Triage matrix&quot;">​</a></h2><p>Classify each PR at creation time:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Example change</th><th>Required review depth</th><th>Merge gate</th></tr></thead><tbody><tr><td><strong>T1 Low risk</strong></td><td>Refactor with no behavior change, docs, internal tooling</td><td>Single reviewer + checks</td><td>CI green + 1 human approval</td></tr><tr><td><strong>T2 Medium risk</strong></td><td>Business logic update, API contract evolution</td><td>Dual perspective review (feature + reliability/security)</td><td>CI green + 2 human approvals</td></tr><tr><td><strong>T3 High risk</strong></td><td>Auth/payments/data migration/security-critical path</td><td>Senior reviewer + domain owner + evidence pack</td><td>CI green + mandatory scenario proof + explicit sign-off</td></tr></tbody></table><p>If reviewer capacity is low, queue T1/T2 optimizations first. Do not weaken T3 controls.</p><hr><h2 id="required-pr-evidence-contract" tabindex="-1">Required PR evidence contract <a class="header-anchor" href="#required-pr-evidence-contract" aria-label="Permalink to &quot;Required PR evidence contract&quot;">​</a></h2><p>Every PR must carry a short, structured payload:</p><ul><li><strong>Intent:</strong> what changed and why now</li><li><strong>Risk notes:</strong> what could break</li><li><strong>Test evidence:</strong> what validates correctness</li><li><strong>Rollback plan:</strong> how to recover if wrong</li><li><strong>Review guidance:</strong> where reviewers should focus first</li></ul><p>This reduces reviewer discovery cost and avoids &quot;read whole diff to infer intent.&quot;</p><hr><h2 id="review-roles-during-capacity-stress" tabindex="-1">Review roles during capacity stress <a class="header-anchor" href="#review-roles-during-capacity-stress" aria-label="Permalink to &quot;Review roles during capacity stress&quot;">​</a></h2><ul><li><strong>Author:</strong> owns clarity, test evidence, and first-pass self-review</li><li><strong>Reviewer:</strong> challenges logic/risk assumptions and verifies evidence quality</li><li><strong>Domain owner (as needed):</strong> validates business/security/operational implications</li><li><strong>Release owner:</strong> can pause merges when queue health or regression rate crosses stop conditions</li></ul><hr><h2 id="escalation-and-stop-conditions" tabindex="-1">Escalation and stop conditions <a class="header-anchor" href="#escalation-and-stop-conditions" aria-label="Permalink to &quot;Escalation and stop conditions&quot;">​</a></h2><p>Pause non-urgent merges and switch to incident-mode review when any of the following persists beyond a short window:</p><ul><li>First meaningful review latency exceeds SLA</li><li>Post-merge defect rate rises above baseline threshold</li><li>High-risk PRs are merged without full required evidence</li><li>Reviewer concentration exceeds agreed limit</li></ul><hr><p><strong>Next:</strong> <a href="./reports/pr-review-continuity/04-pr-design-and-work-slicing-patterns.html">PR design and work slicing patterns</a></p>',23)])])}const w=i(o,[["render",s]]);export{m as __pageData,w as default};
